begin;
create extension if not exists pgtap with schema extensions;
grant usage on schema extensions to authenticated,anon,service_role;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) values
('60000000-0000-4000-8000-000000000001','billing-owner@test.example','{"nome":"Dono Cobrança","tipo":"fornecedor","empresa":"Empresa Cobrança","cnpj":"11222333000181","telefone":"11999999999","termos":true,"termos_versao":"2026-10-19","privacidade_versao":"2026-10-19"}'),
('60000000-0000-4000-8000-000000000002','billing-other@test.example','{"nome":"Outro Cobrança","tipo":"sindico","cidade":"São Paulo","estado":"SP","termos":true,"termos_versao":"2026-10-19","privacidade_versao":"2026-10-19"}');
select set_config('test.sid',(select id::text from public.fornecedores where dono_id='60000000-0000-4000-8000-000000000001'),true);
update public.fornecedores set status='publicado',slug='empresa-billing',teste_inicio=now(),teste_fim=now()+interval '90 days' where id=current_setting('test.sid')::uuid;
select is((select status from public.assinaturas where fornecedor_id=current_setting('test.sid')::uuid),'teste','aprovação com data cria assinatura de teste');
insert into public.midias(fornecedor_id,url,ordem) select current_setting('test.sid')::uuid,'https://example.com/'||n,n from generate_series(1,5)n;
insert into public.cases(fornecedor_id,condominio) values(current_setting('test.sid')::uuid,'Case de exemplo');
select is((select count(*) from public.midias where not oculto_por_plano),5::bigint,'Premium de teste exibe cinco fotos');
update public.assinaturas set teste_ate=now()-interval '1 day',criado_em=now()-interval '91 days' where fornecedor_id=current_setting('test.sid')::uuid;
select is(private.effective_plan(current_setting('test.sid')::uuid),'gratuito','teste vencido já resolve Grátis antes do job');
select set_config('request.jwt.claims','{"role":"service_role"}',true);
set local role service_role;
select is(public.processar_ciclo_planos(),1,'rotina migra teste vencido');
select is(public.processar_ciclo_planos(),0,'rotina é idempotente');
reset role;
select is((select status from public.assinaturas),'gratuita','assinatura mudou para gratuita');
select is((select count(*) from public.midias where not oculto_por_plano),1::bigint,'somente uma foto fica visível');
select is((select count(*) from public.midias),5::bigint,'fotos excedentes não foram apagadas');
select ok((select oculto_por_plano from public.cases),'case preservado e oculto');
select is((select count(*) from public.email_outbox where template='fim_teste'),1::bigint,'fim do teste enfileira e-mail uma vez');
select set_config('test.seg',(select id::text from public.segmentos where ativo limit 1),true);
insert into private.quotation_requests(id,ip_hash,payload_hash) select ('61000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,repeat('a',64),repeat('b',64) from generate_series(1,4)n;
insert into public.consentimentos(id,email,documento,versao,origem) values('62000000-0000-4000-8000-000000000001','sindico@example.com','privacidade','2026-10-20','teste');
insert into public.leads(id,pedido_id,fornecedor_id,segmento_id,nome,email,telefone,condominio_nome,cidade,uf,unidades,urgencia,mensagem,consentimento_id)
select ('63000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('61000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,current_setting('test.sid')::uuid,current_setting('test.seg')::uuid,'Síndico Teste','sindico@example.com','11999999999','Condomínio Teste','Campinas','SP',30,'planejamento','Mensagem particular e contatos não podem vazar','62000000-0000-4000-8000-000000000001' from generate_series(1,4)n;
select is((select count(*) from public.leads where status='novo'),3::bigint,'primeiros três pedidos liberados');
select is((select status from public.leads where id='63000000-0000-4000-8000-000000000004'),'bloqueado_plano','quarto pedido bloqueado');
set local role authenticated;
select set_config('request.jwt.claim.sub','60000000-0000-4000-8000-000000000001',true);
select throws_ok($$select * from public.leads$$,'42501',null,'Data API não expõe tabela de contatos');
select ok(not exists(select 1 from jsonb_array_elements(public.listar_orcamentos(current_setting('test.sid')::uuid)) x where x->>'id'='63000000-0000-4000-8000-000000000004' and (x ? 'email' or x ? 'nome' or x ? 'mensagem')),'RPC redige dados pessoais');
select throws_ok($$select public.liberar_orcamento('63000000-0000-4000-8000-000000000004')$$,'P0001','Saldo insuficiente. Escolha um pacote de créditos.','sem saldo não libera');
select throws_ok($$select public.aplicar_evento_stripe('evt_fake','checkout.session.completed','{}')$$,'42501',null,'cliente não forja webhook');
select throws_ok($$update public.assinaturas set status='ativa'$$,'42501',null,'cliente não muda plano diretamente');
select throws_ok($$select public.preparar_checkout(current_setting('test.sid')::uuid,'creditos_10','64000000-0000-4000-8000-000000000001')$$,'P0001','Preço ainda não configurado','compra desabilitada sem preço final');
select set_config('request.jwt.claim.sub','60000000-0000-4000-8000-000000000002',true);
select throws_ok($$select public.resumo_plano(current_setting('test.sid')::uuid)$$,'P0001','Acesso negado','outra conta não vê extrato');
select throws_ok($$select public.liberar_orcamento('63000000-0000-4000-8000-000000000004')$$,'P0001','Somente o proprietário pode usar créditos','outra conta não usa saldo');
reset role;
update public.tabela_precos set preco_centavos=4900 where codigo='creditos_10';
set local role authenticated;
select set_config('request.jwt.claim.sub','60000000-0000-4000-8000-000000000001',true);
select is(public.preparar_checkout(current_setting('test.sid')::uuid,'creditos_10','64000000-0000-4000-8000-000000000001')->>'valor_centavos','4900','preço vem do servidor');
select is(public.preparar_checkout(current_setting('test.sid')::uuid,'creditos_10','64000000-0000-4000-8000-000000000001')->>'id','64000000-0000-4000-8000-000000000001','repetir checkout mantém pedido');
reset role;
set local role service_role;
select lives_ok($$select public.vincular_checkout('64000000-0000-4000-8000-000000000001','cs_test_valid',null)$$,'servidor vincula checkout');
select throws_ok($$select public.aplicar_evento_stripe('evt_wrong','checkout.session.completed','{"session_id":"cs_test_valid","amount_total":1,"currency":"brl","payment_status":"paid"}')$$,'P0001','Pagamento não confere com o pedido','valor divergente não credita');
select lives_ok($$select public.aplicar_evento_stripe('evt_paid','checkout.session.completed','{"session_id":"cs_test_valid","amount_total":4900,"currency":"brl","payment_status":"paid","payment_intent":"pi_test_valid","customer":"cus_test"}')$$,'compra confirmada credita');
select is(public.aplicar_evento_stripe('evt_paid','checkout.session.completed','{}')->>'duplicado','true','evento repetido ignorado');
select lives_ok($$select public.aplicar_evento_stripe('evt_paid_alias','checkout.session.completed','{"session_id":"cs_test_valid","amount_total":4900,"currency":"brl","payment_status":"paid","payment_intent":"pi_test_valid","customer":"cus_test"}')$$,'outro evento do mesmo checkout não duplica');
reset role;
select is((select sum(quantidade) from public.creditos_extrato),10::bigint,'compra soma exatamente dez');
set local role authenticated;
select lives_ok($$select public.liberar_orcamento('63000000-0000-4000-8000-000000000004')$$,'libera quarto pedido atomicamente');
select lives_ok($$select public.liberar_orcamento('63000000-0000-4000-8000-000000000004')$$,'retry de liberação não gasta novamente');
select is(public.resumo_plano(current_setting('test.sid')::uuid)->>'saldo','9','um crédito debitado');
select ok(exists(select 1 from jsonb_array_elements(public.listar_orcamentos(current_setting('test.sid')::uuid)) x where x->>'id'='63000000-0000-4000-8000-000000000004' and x->>'email'='sindico@example.com'),'contato liberado visível pelo RPC');
reset role;
set local role service_role;
select lives_ok($$select public.aplicar_evento_stripe('evt_refund','charge.refunded','{"payment_intent":"pi_test_valid","amount_refunded":2450}')$$,'estorno parcial registrado');
select lives_ok($$select public.aplicar_evento_stripe('evt_refund_alias','charge.refunded','{"payment_intent":"pi_test_valid","amount_refunded":2450}')$$,'estorno acumulado repetido não debita duas vezes');
reset role;
select is((select sum(quantidade) from public.creditos_extrato),4::bigint,'meio estorno retira cinco créditos uma vez');
insert into public.assinaturas(fornecedor_id,plano,status,periodo_ate,stripe_subscription_id) values(current_setting('test.sid')::uuid,'premium','ativa',now()+interval '30 days','sub_test') on conflict(fornecedor_id) do update set plano='premium',status='ativa',periodo_ate=now()+interval '30 days',stripe_subscription_id='sub_test';
select is((select count(*) from public.midias where not oculto_por_plano),5::bigint,'upgrade restaura todas as fotos');
select ok(not (select oculto_por_plano from public.cases),'upgrade restaura o case');
set local role service_role;
select lives_ok($$select public.aplicar_evento_stripe('evt_pastdue','invoice.payment_failed','{"subscription":"sub_test","status":"past_due"}')$$,'falha de cobrança inicia carência');
reset role;
select is(private.effective_plan(current_setting('test.sid')::uuid),'premium','benefícios mantidos na carência');
update public.assinaturas set carencia_ate=now()-interval '1 hour';
set local role service_role;
select is(public.processar_ciclo_planos(),1,'fim da carência migra Grátis');
reset role;
select is(private.effective_plan(current_setting('test.sid')::uuid),'gratuito','carência encerrada retira benefício');
select ok(exists(select 1 from public.audit_log where tabela='creditos_extrato' and acao='INSERT'),'extrato auditado');
select * from finish();rollback;
